create table public.evidence_policies(id uuid primary key default gen_random_uuid(),service public.job_service not null,service_subtype text,territory text,provider_company_id uuid references public.provider_companies on delete cascade,job_id uuid references public.jobs on delete cascade,version int not null default 1,effective_from timestamptz not null default now(),effective_to timestamptz,active boolean not null default true,reviewer_override_allowed boolean not null default false,created_by uuid references public.profiles,updated_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_to is null or effective_to>effective_from));
create table public.evidence_policy_rules(id uuid primary key default gen_random_uuid(),policy_id uuid not null references public.evidence_policies on delete cascade,evidence_type text not null check(evidence_type in ('before_photo','after_photo','item_condition_photo','damage_photo','disposal_receipt','donation_receipt','work_summary','item_summary','customer_summary','damage_declaration','incident_declaration','missing_item_declaration','prohibited_material_declaration','customer_presence_declaration','access_problem_declaration')),media_purpose text check(media_purpose in ('before','after','item_condition','damage','disposal_receipt','donation_receipt')),minimum_files int not null default 0 check(minimum_files>=0),maximum_files int check(maximum_files is null or maximum_files>=minimum_files),allowed_mime_types text[] not null default '{}',maximum_file_bytes bigint check(maximum_file_bytes is null or maximum_file_bytes between 1 and 10485760),customer_visible_default boolean not null default false,receipt_required boolean not null default false,notes_required boolean not null default false,declaration_required boolean not null default false,unique(policy_id,evidence_type));
create table public.completion_drafts(id uuid primary key default gen_random_uuid(),assignment_id uuid not null unique references public.assignments on delete restrict,job_id uuid not null references public.jobs on delete restrict,provider_company_id uuid not null references public.provider_companies on delete restrict,crew_id uuid not null references public.crews on delete restrict,created_by uuid not null references public.profiles on delete restrict,policy_id uuid not null references public.evidence_policies on delete restrict,status text not null default 'draft' check(status in ('draft','submitted','abandoned')),payload jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.completion_draft_media(id uuid primary key default gen_random_uuid(),draft_id uuid not null references public.completion_drafts on delete restrict,job_id uuid not null references public.jobs on delete restrict,uploaded_by uuid not null references public.profiles on delete restrict,storage_path text not null unique,purpose text not null check(purpose in ('before','after','item_condition','damage','disposal_receipt','donation_receipt')),customer_visible boolean not null,mime_type text not null,byte_size bigint not null,created_at timestamptz not null default now());
do $$ declare t text;begin foreach t in array array['evidence_policies','evidence_policy_rules','completion_drafts','completion_draft_media'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create trigger set_evidence_policies_updated before update on public.evidence_policies for each row execute function public.set_updated_at();create trigger set_completion_drafts_updated before update on public.completion_drafts for each row execute function public.set_updated_at();create trigger immutable_completion_draft_media before update or delete on public.completion_draft_media for each row execute function public.prevent_event_mutation();
create policy "operations read evidence policies" on public.evidence_policies for select to authenticated using(public.has_any_role(array['dispatcher','compliance_admin','super_admin']::public.app_role[]) or (provider_company_id is not null and public.can_manage_provider(provider_company_id)) or (job_id is not null and public.crew_has_assigned_job(job_id)));
create policy "operations read evidence rules" on public.evidence_policy_rules for select to authenticated using(exists(select 1 from public.evidence_policies p where p.id=evidence_policy_rules.policy_id and (public.has_any_role(array['dispatcher','compliance_admin','super_admin']::public.app_role[]) or (p.provider_company_id is not null and public.can_manage_provider(p.provider_company_id)) or (p.job_id is not null and public.crew_has_assigned_job(p.job_id)))));
create policy "crew reads completion drafts" on public.completion_drafts for select to authenticated using(public.crew_has_assigned_job(job_id));create policy "provider reads completion drafts" on public.completion_drafts for select to authenticated using(public.can_manage_provider(provider_company_id));create policy "dispatch reads completion drafts" on public.completion_drafts for select to authenticated using(public.has_any_role(array['dispatcher','super_admin']::public.app_role[]));
create policy "crew reads draft media" on public.completion_draft_media for select to authenticated using(public.crew_has_assigned_job(job_id));create policy "provider reads draft media" on public.completion_draft_media for select to authenticated using(exists(select 1 from public.completion_drafts d where d.id=completion_draft_media.draft_id and public.can_manage_provider(d.provider_company_id)));create policy "dispatch reads draft media" on public.completion_draft_media for select to authenticated using(public.has_any_role(array['dispatcher','super_admin']::public.app_role[]));

with p as (insert into public.evidence_policies(service,version,active) values('move',1,true) returning id) insert into public.evidence_policy_rules(policy_id,evidence_type,media_purpose,minimum_files,maximum_files,allowed_mime_types,maximum_file_bytes,customer_visible_default,declaration_required,notes_required) select id,x.type,x.purpose,x.minimum,x.maximum,array['image/jpeg','image/png','image/webp'],10485760,x.visible,x.declaration,x.notes from p cross join (values('before_photo','before',1,10,true,false,false),('after_photo','after',1,10,true,false,false),('work_summary',null,0,null,false,false,true),('item_summary',null,0,null,false,false,true),('customer_summary',null,0,null,true,false,true),('damage_declaration',null,0,null,false,true,false),('incident_declaration',null,0,null,false,true,false)) x(type,purpose,minimum,maximum,visible,declaration,notes);
with p as (insert into public.evidence_policies(service,version,active) values('remove',1,true) returning id) insert into public.evidence_policy_rules(policy_id,evidence_type,media_purpose,minimum_files,maximum_files,allowed_mime_types,maximum_file_bytes,customer_visible_default,declaration_required,notes_required) select id,x.type,x.purpose,x.minimum,x.maximum,array['image/jpeg','image/png','image/webp'],10485760,x.visible,x.declaration,x.notes from p cross join (values('before_photo','before',1,10,true,false,false),('after_photo','after',1,10,true,false,false),('work_summary',null,0,null,false,false,true),('item_summary',null,0,null,false,false,true),('customer_summary',null,0,null,true,false,true),('damage_declaration',null,0,null,false,true,false),('incident_declaration',null,0,null,false,true,false),('prohibited_material_declaration',null,0,null,false,true,false)) x(type,purpose,minimum,maximum,visible,declaration,notes);

create or replace function public.start_completion_draft(p_assignment uuid,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_a public.assignments%rowtype;v_job public.jobs%rowtype;v_policy uuid;v_id uuid;begin select id into v_id from public.completion_drafts where assignment_id=p_assignment and status='draft';if v_id is not null then return v_id;end if;if not public.has_any_role(array['crew_lead']::public.app_role[]) then raise exception 'crew lead required';end if;select * into v_a from public.assignments where id=p_assignment for update;if not found or v_a.status<>'in_progress' or not exists(select 1 from public.crew_members where crew_id=v_a.crew_id and profile_id=auth.uid()) then raise exception 'assignment not available';end if;select * into v_job from public.jobs where id=v_a.job_id;select p.id into v_policy from public.evidence_policies p where p.active and p.service=v_job.service and p.effective_from<=now() and (p.effective_to is null or p.effective_to>now()) and (p.job_id=v_job.id or p.provider_company_id=v_a.provider_company_id or (p.job_id is null and p.provider_company_id is null)) order by (p.job_id is not null) desc,(p.provider_company_id is not null) desc,p.version desc limit 1;if v_policy is null then raise exception 'completion evidence policy unavailable';end if;insert into public.completion_drafts(assignment_id,job_id,provider_company_id,crew_id,created_by,policy_id) values(v_a.id,v_a.job_id,v_a.provider_company_id,v_a.crew_id,auth.uid(),v_policy) returning id into v_id;insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata,request_id) values(auth.uid(),'completion.draft_started','completion_draft',v_id,jsonb_build_object('assignment_id',p_assignment,'policy_id',v_policy),p_request_id);return v_id;end $$;
revoke all on function public.start_completion_draft(uuid,uuid) from public;grant execute on function public.start_completion_draft(uuid,uuid) to authenticated;

create or replace function public.completion_draft_readiness(p_draft uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$ declare v_d public.completion_drafts%rowtype;v_missing jsonb;begin select * into v_d from public.completion_drafts where id=p_draft;if not found or not (public.crew_has_assigned_job(v_d.job_id) or public.can_manage_provider(v_d.provider_company_id) or public.has_any_role(array['dispatcher','super_admin']::public.app_role[])) then raise exception 'draft not found';end if;select coalesce(jsonb_agg(jsonb_build_object('evidence_type',r.evidence_type,'required',r.minimum_files,'present',(select count(*) from public.completion_draft_media m where m.draft_id=v_d.id and m.purpose=r.media_purpose))),'[]') into v_missing from public.evidence_policy_rules r where r.policy_id=v_d.policy_id and r.minimum_files>0 and (select count(*) from public.completion_draft_media m where m.draft_id=v_d.id and m.purpose=r.media_purpose)<r.minimum_files;return jsonb_build_object('ready',jsonb_array_length(v_missing)=0,'missing',v_missing,'policy_id',v_d.policy_id);end $$;
revoke all on function public.completion_draft_readiness(uuid) from public;grant execute on function public.completion_draft_readiness(uuid) to authenticated;

create or replace function public.register_completion_draft_media(p_draft uuid,p_path text,p_purpose text,p_mime text,p_size bigint) returns uuid language plpgsql security definer set search_path=public,storage as $$ declare v_d public.completion_drafts%rowtype;v_rule public.evidence_policy_rules%rowtype;v_id uuid;begin select * into v_d from public.completion_drafts where id=p_draft;if not found or v_d.status<>'draft' or not public.crew_has_assigned_job(v_d.job_id) then raise exception 'draft not found';end if;select * into v_rule from public.evidence_policy_rules where policy_id=v_d.policy_id and media_purpose=p_purpose;if not found then raise exception 'evidence type is not allowed';end if;if p_path not like auth.uid()::text||'/'||v_d.job_id::text||'/%' or not(p_mime=any(v_rule.allowed_mime_types)) or p_size not between 1 and least(coalesce(v_rule.maximum_file_bytes,10485760),10485760) then raise exception 'invalid evidence file';end if;if (select count(*) from public.completion_draft_media where draft_id=p_draft and purpose=p_purpose)>=coalesce(v_rule.maximum_files,100) then raise exception 'maximum evidence count reached';end if;if not exists(select 1 from storage.objects where bucket_id='completion-media' and name=p_path and owner_id=auth.uid()::text) then raise exception 'media object not found';end if;insert into public.completion_draft_media(draft_id,job_id,uploaded_by,storage_path,purpose,customer_visible,mime_type,byte_size) values(p_draft,v_d.job_id,auth.uid(),p_path,p_purpose,v_rule.customer_visible_default,p_mime,p_size) returning id into v_id;insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'completion.draft_evidence_uploaded','completion_draft_media',v_id,jsonb_build_object('draft_id',p_draft,'purpose',p_purpose));return v_id;end $$;
revoke all on function public.register_completion_draft_media(uuid,text,text,text,bigint) from public;grant execute on function public.register_completion_draft_media(uuid,text,text,text,bigint) to authenticated;

create or replace function public.finalize_completion_draft(p_draft uuid,p_payload jsonb,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_d public.completion_drafts%rowtype;v_ready jsonb;v_submission uuid;begin select * into v_d from public.completion_drafts where id=p_draft for update;if not found or v_d.status<>'draft' then raise exception 'draft is not available';end if;v_ready:=public.completion_draft_readiness(p_draft);if not coalesce((v_ready->>'ready')::boolean,false) then raise exception 'required completion evidence is missing: %',v_ready->'missing';end if;v_submission:=public.submit_completion(v_d.assignment_id,p_payload,p_request_id);insert into public.completion_media(submission_id,job_id,uploaded_by,storage_path,purpose,customer_visible,mime_type,byte_size) select v_submission,job_id,uploaded_by,storage_path,purpose,customer_visible,mime_type,byte_size from public.completion_draft_media where draft_id=p_draft;update public.completion_drafts set status='submitted',payload=jsonb_build_object('submission_id',v_submission) where id=p_draft;insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'completion.draft_finalized','completion_draft',p_draft,jsonb_build_object('submission_id',v_submission,'policy_id',v_d.policy_id));return v_submission;end $$;
revoke all on function public.finalize_completion_draft(uuid,jsonb,uuid) from public;grant execute on function public.finalize_completion_draft(uuid,jsonb,uuid) to authenticated;

revoke all on function public.submit_completion(uuid,jsonb,uuid) from authenticated;
